"""Deutsch — Tugenden (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Was soll laut einem von Imam al-Buchari überlieferten Hadith jemand, der an Allah und den Jüngsten Tag glaubt, mit seinen Worten tun?", ["Gutes sagen oder schweigen", "Laut sprechen", "Nie sprechen", "Gerüchte weitergeben"], "Der Prophet ﷺ sagte: „Wer an Allah und den Jüngsten Tag glaubt, soll Gutes sagen oder schweigen.“"),
"virtues_002": ("Wen soll ein Gläubiger laut demselben Hadith außer seinem Gast noch ehren?", ["Seinen Nachbarn", "Seinen Händler", "Seinen Rivalen", "Einen Fremden"], "Der Hadith fährt fort: „…und wer an Allah und den Jüngsten Tag glaubt, soll seinen Nachbarn ehren.“"),
"virtues_003": ("Wen zu ehren erwähnt derselbe Hadith außerdem, wenn er zu einem nach Hause kommt?", ["Den Gast", "Nur den Nachbarn", "Den Händler", "Einen fernen unbekannten Reisenden"], "Der vollständige Hadith sagt: „…wer an Allah und den Jüngsten Tag glaubt, soll seinen Gast ehren.“"),
"virtues_004": ("Laut einem authentischen Hadith ist der Glaube eines Gläubigen nicht vollständig, bis er für seinen Bruder liebt, was er liebt für…", ["sich selbst", "sein Vermögen", "nur seine Familie", "sein Land"], "Der Prophet ﷺ sagte: „Keiner von euch glaubt wahrhaftig, bis er für seinen Bruder liebt, was er für sich selbst liebt.“"),
"virtues_005": ("Laut einem authentischen Hadith ist der wahre Muslim derjenige, vor dessen Zunge und ___ die anderen sicher sind.", ["Hand", "Vermögen", "Blick", "Stimme"], "Der Prophet ﷺ sagte: „Der Muslim ist derjenige, vor dessen Zunge und Hand die anderen Muslime sicher sind.“"),
"virtues_006": ("Der Koran gebietet Güte gegenüber den Eltern und verbietet, ihnen selbst welches Wort des Unmuts zu sagen?", ["„Uff“ (ein Laut der Ungeduld)", "„Nein“", "„Genug“", "„Warte“"], "Der Koran fordert höchste Güte gegenüber den Eltern und verbietet selbst das leiseste Wort der Verachtung."),
"virtues_007": ("Womit vergleicht der Koran die üble Nachrede (schlecht über einen Abwesenden zu reden)?", ["Mit dem Essen des Fleisches des eigenen toten Bruders", "Mit dem Trinken von Salzwasser", "Mit dem Gehen in der Dunkelheit", "Mit dem Säen in Sand"], "„Möchte einer von euch das Fleisch seines toten Bruders essen? Ihr würdet es verabscheuen!“: So hässlich ist üble Nachrede."),
"virtues_008": ("Wie beschreibt der Koran das Verhältnis zwischen den Gläubigen?", ["Sie sind Brüder", "Sie sind Konkurrenten", "Sie sind Fremde", "Sie sind Geschäftspartner"], "„Die Gläubigen sind doch Brüder, so stiftet Frieden zwischen euren beiden Brüdern.“"),
"virtues_009": ("Was sagt der Koran über das Verspotten anderer Menschen?", ["Es ist verboten: Die Verspotteten sind vielleicht besser als die Spötter", "Es ist unter Freunden erlaubt", "Es ist erlaubt, wenn es lustig ist", "Es ist den Dichtern vorbehalten"], "„Kein Volk soll ein anderes verspotten: Vielleicht sind jene besser als sie.“"),
"virtues_010": ("Was verspricht Allah laut Koran dem Dankbaren?", ["Er wird ihm gewiss mehr geben", "Ein langes Leben", "Sofortigen Reichtum", "Eine Reise"], "„Wenn ihr dankbar seid, werde Ich euch gewiss noch mehr geben.“"),
"virtues_011": ("Wie werden die Geduldigen (Sabirun) laut Koran ihren Lohn erhalten?", ["Vollständig, ohne Maß", "Alles auf einmal", "Nach vierzig Tagen", "Nach ihrem Vermögen"], "„Den Geduldigen wird ihr Lohn vollständig gegeben, ohne Abrechnung.“"),
"virtues_012": ("„Esst und trinkt, aber…“: Wie geht dieser Vers weiter?", ["Seid nicht verschwenderisch", "Teilt nicht", "Sprecht nicht", "Geht nicht hinaus"], "„Esst und trinkt, aber seid nicht maßlos: Allah liebt die Maßlosen nicht.“"),
"virtues_013": ("Welcher oft in der Freitagspredigt rezitierte Vers fasst zusammen, was Allah gebietet?", ["„Allah gebietet Gerechtigkeit und gutes Handeln“", "„Allah gebietet den Handel“", "„Allah gebietet das Reisen“", "„Allah gebietet das Schweigen“"], "„Allah gebietet Gerechtigkeit, gutes Handeln und Freigebigkeit gegenüber den Verwandten…“: jeden Freitag rezitiert."),
"virtues_014": ("Gegen wen beginnt die Sure Al-Mutaffifin mit „Wehe…“?", ["Gegen die, die bei Maß und Gewicht betrügen", "Gegen die, die schlafen", "Gegen die, die reisen", "Gegen die, die schweigen"], "„Wehe den Betrügern: die volles Maß verlangen, wenn sie empfangen, aber weniger geben, wenn sie für andere messen!“"),
"virtues_015": ("Wie sind laut Sure Ad-Duha die Waise und der Bittende zu behandeln?", ["Weder unterdrückt noch abgewiesen", "Ignoriert", "Zu anderen geschickt", "Später angesprochen"], "„Was die Waise betrifft, so unterdrücke sie nicht; und was den Bittenden betrifft, so weise ihn nicht ab.“"),
"virtues_016": ("Wie gebietet der Koran, mit den Menschen zu sprechen?", ["Mit guten Worten", "Mit sehr leiser Stimme", "So wenig wie möglich", "Nur mit Verwandten"], "„…und sprecht zu den Menschen auf gute Weise“: Freundliche Rede ist selbst Gottesdienst."),
"virtues_017": ("Was sagt Luqman in seinen Ratschlägen an seinen Sohn über das Gehen und den Stolz?", ["Geh nicht hochmütig auf der Erde", "Geh immer schnell", "Geh nur nachts", "Geh nie allein"], "„Wende dein Gesicht nicht hochmütig von den Menschen ab und geh nicht hochmütig auf der Erde.“"),
"virtues_018": ("Wonach werden laut dem allerersten Hadith der Sammlung al-Bucharis die Taten beurteilt?", ["Nach den Absichten", "Nach den Ergebnissen", "Nach den Gewohnheiten", "Nach den Zeugen"], "„Die Taten sind entsprechend den Absichten, und jedem Menschen wird nur das zuteil, was er beabsichtigt hat.“"),
"virtues_019": ("Wohin führt laut einem Hadith bei al-Buchari die Wahrhaftigkeit (Sidq)?", ["Zur Rechtschaffenheit, und die Rechtschaffenheit führt ins Paradies", "Zum Reichtum", "Zum Ruhm", "Zur Stärke"], "„Wahrhaftigkeit führt zur Rechtschaffenheit, und Rechtschaffenheit führt ins Paradies; Lüge führt zur Verderbtheit, und Verderbtheit führt ins Feuer.“"),
"virtues_020": ("Was sind laut einem authentischen Hadith die drei Zeichen des Heuchlers?", ["Er lügt, wenn er spricht, bricht sein Versprechen und verrät das Vertrauen", "Er schläft, isst und redet zu viel", "Er reist, handelt und singt", "Er betet wenig, fastet wenig und liest wenig"], "„Die Zeichen des Heuchlers sind drei: Wenn er spricht, lügt er; wenn er verspricht, bricht er es; und wenn ihm vertraut wird, verrät er.“"),
"virtues_021": ("Ein Mann bat den Propheten ﷺ um Rat; was wiederholte er ihm mehrmals?", ["„Werde nicht zornig“", "„Reise viel“", "„Iss wenig“", "„Sprich laut“"], "Der Mann sagte: „Rate mir.“ Er antwortete: „Werde nicht zornig.“ Der Mann fragte erneut, und er wiederholte: „Werde nicht zornig.“"),
"virtues_022": ("Wer ist laut dem Propheten ﷺ wirklich stark?", ["Wer sich im Zorn beherrscht", "Wer im Ringkampf siegt", "Wer die schwersten Lasten trägt", "Wer am schnellsten läuft"], "„Der Starke ist nicht, wer andere im Ringkampf besiegt; der Starke ist, wer sich im Zorn beherrscht.“"),
"virtues_023": ("Wovon ist die Schamhaftigkeit (Haya') laut einem Hadith bei al-Buchari ein Teil?", ["Vom Glauben", "Von der Schwäche", "Vom Reichtum", "Von tadelnswerter Schüchternheit"], "Als er einen Mann seinen Bruder wegen seiner Schamhaftigkeit tadeln sah, sagte der Prophet ﷺ: „Lass ihn, denn die Schamhaftigkeit ist ein Teil des Glaubens.“"),
"virtues_024": ("Was sagte der Prophet ﷺ zu einem Mann, der prahlte, keines seiner zehn Kinder je geküsst zu haben?", ["„Wer keine Barmherzigkeit zeigt, dem wird keine Barmherzigkeit zuteil“", "„Du hast recht“", "„Kinder zählen nicht“", "„Das ist Privatsache“"], "Der Prophet ﷺ küsste seine Enkel; dem erstaunten Al-Aqra' antwortete er: „Man la yarham la yurham.“"),
"virtues_025": ("Für welche Tat wurde laut einem Hadith bei al-Buchari einem Mann vergeben?", ["Dafür, einem durstigen Hund Wasser zu geben", "Dafür, einen Brunnen zu bauen", "Dafür, einen Baum zu pflanzen", "Dafür, einen Wolf zu vertreiben"], "Der Mann stieg in einen Brunnen, füllte seinen Schuh mit Wasser und tränkte den vor Durst hechelnden Hund; Allah vergab ihm."),
"virtues_026": ("Warum wurde laut einem authentischen Hadith eine Frau bestraft?", ["Weil sie eine Katze einsperrte, ohne sie zu füttern oder Futter suchen zu lassen", "Weil sie eine Katze verkaufte", "Weil sie eine Katze aus ihrem Haus jagte", "Weil sie zu viele Katzen aufnahm"], "„Eine Frau wurde wegen einer Katze bestraft, die sie eingesperrt hatte, bis sie starb: Sie fütterte sie nicht und ließ sie nicht von den Geschöpfen der Erde fressen.“"),
"virtues_027": ("Über wen sagte der Prophet ﷺ, Jibril habe ihn so oft empfohlen, dass er dachte, er würde ihn zum Erben machen?", ["Den Nachbarn", "Den Gast", "Die Waise", "Den Reisenden"], "„Jibril hörte nicht auf, mir den Nachbarn zu empfehlen, bis ich dachte, er würde ihn erben lassen.“"),
"virtues_028": ("Wie viele Rechte hat ein Muslim laut einem Hadith bei al-Buchari gegenüber seinem muslimischen Bruder?", ["Fünf", "Drei", "Sieben", "Zehn"], "„Den Gruß erwidern, den Kranken besuchen, dem Leichenzug folgen, die Einladung annehmen und dem Niesenden antworten.“"),
"virtues_029": ("Was antwortete der Prophet ﷺ auf die Frage „Welcher Islam ist der beste?“", ["Menschen zu speisen und die zu grüßen, die du kennst und die du nicht kennst", "Moscheen zu bauen", "Viel zu reisen", "Wenig zu sprechen"], "„Speise andere und entbiete den Friedensgruß dem, den du kennst, und dem, den du nicht kennst.“"),
"virtues_030": ("Womit vergleicht der Prophet ﷺ die Gläubigen in ihrer Liebe und gegenseitigen Unterstützung?", ["Mit einem einzigen Körper: Leidet ein Glied, wacht der ganze Körper mit Fieber", "Mit einem Wald", "Mit einer Karawane", "Mit einer Herde"], "„Die Gläubigen sind in ihrer gegenseitigen Liebe, Barmherzigkeit und Zuneigung wie ein einziger Körper.“"),
"virtues_031": ("Was ist laut dem Propheten ﷺ „die verlogenste Rede“?", ["Der Verdacht (Zann)", "Die Dichtung", "Der Scherz", "Das Schweigen"], "„Hütet euch vor dem Verdacht, denn der Verdacht ist die verlogenste Rede.“"),
"virtues_032": ("Wie viele Tage höchstens darf ein Muslim laut einem authentischen Hadith seinen Bruder meiden?", ["Drei Tage", "Sieben Tage", "Einen Monat", "Ein Jahr"], "„Es ist einem Mann nicht erlaubt, seinen Bruder länger als drei Nächte zu meiden… und der Bessere von beiden ist der, der zuerst grüßt.“"),
"virtues_033": ("Welchen Wert hat laut dem Propheten ﷺ jede gute Tat, so klein sie auch sei?", ["Sie ist eine Spende (Sadaqa)", "Sie zählt nicht", "Sie ist einen Dinar wert", "Sie ersetzt das Gebet"], "„Jede gute Tat ist eine Sadaqa.“"),
"virtues_034": ("Was ist laut einem Hadith bei Sahih Muslim der geringste Zweig des Glaubens?", ["Etwas Schädliches vom Weg zu entfernen", "Eine Moschee zu bauen", "Einen Juz' zu rezitieren", "Einen Tag zu fasten"], "„Der Glaube hat siebzig und einige Zweige: Der höchste ist ‚la ilaha illa Allah‘, der geringste ist, etwas Schädliches vom Weg zu entfernen; und die Schamhaftigkeit ist ein Zweig des Glaubens.“"),
"virtues_035": ("Laut einem Hadith bei Sahih Muslim ist die Reinheit (Tahara)…", ["Die Hälfte des Glaubens", "Ein Drittel des Glaubens", "Ein Zehntel des Glaubens", "Ohne Bezug zum Glauben"], "„Die Reinheit ist die Hälfte des Glaubens, und ‚al-hamdu li-Llah‘ füllt die Waage.“"),
"virtues_036": ("Der Prophet ﷺ sagte: „Die Religion ist Nasiha (aufrichtiger Rat).“ Gegenüber wem?", ["Gegenüber Allah, Seinem Buch, Seinem Gesandten, den Führern und allen Muslimen", "Nur gegenüber sich selbst", "Gegenüber den Reichen", "Gegenüber Fremden"], "Man fragte: „Gegenüber wem?“ Er sagte: „Gegenüber Allah, Seinem Buch, Seinem Gesandten, den Führern der Muslime und ihrem gemeinen Volk.“"),
"virtues_037": ("Worauf schaut Allah laut einem Hadith bei Sahih Muslim bei Seinen Dienern?", ["Auf ihre Herzen und ihre Taten", "Auf ihr Aussehen", "Auf ihren Reichtum", "Auf ihre Zahl"], "„Allah schaut nicht auf eure Körper und nicht auf euer Aussehen, sondern Er schaut auf eure Herzen und eure Taten.“"),
"virtues_038": ("Was tut Allah laut einem Hadith bei Sahih Muslim für den, der einem Gläubigen eine Not dieser Welt abnimmt?", ["Er nimmt ihm eine Not am Tag der Auferstehung ab", "Er macht ihn reich", "Er schenkt ihm ein langes Leben", "Er macht ihn berühmt"], "„Wer einem Gläubigen eine Not dieser Welt abnimmt, dem nimmt Allah eine Not am Tag der Auferstehung ab.“"),
"virtues_039": ("Was tut Allah laut dem Propheten ﷺ für den, der einen Weg auf der Suche nach Wissen beschreitet?", ["Er erleichtert ihm einen Weg ins Paradies", "Er befreit ihn vom Gebet", "Er macht ihn reich", "Er macht ihn zum König"], "„Wer einen Weg auf der Suche nach Wissen beschreitet, dem erleichtert Allah dadurch einen Weg ins Paradies.“"),
"virtues_040": ("Wer ist laut einem Hadith bei al-Buchari „der Beste von euch“?", ["Wer den Koran lernt und ihn lehrt", "Wer am besten spricht", "Wer am meisten besitzt", "Wer am meisten reist"], "„Der Beste von euch ist, wer den Koran lernt und ihn lehrt.“"),
"virtues_041": ("Wie definierte der Prophet ﷺ den Hochmut (Kibr)?", ["Die Wahrheit zurückzuweisen und auf die Menschen herabzusehen", "Schöne Kleidung zu tragen", "Schöne Schuhe zu mögen", "Schnell zu gehen"], "Zu dem Mann, der schöne Kleidung liebte, sagte er: „Allah ist schön und liebt die Schönheit. Hochmut ist, die Wahrheit zurückzuweisen und die Menschen zu verachten.“"),
"virtues_042": ("Welche zwei Gaben nutzen laut einem Hadith bei al-Buchari viele Menschen nicht?", ["Gesundheit und freie Zeit", "Geld und Ruhm", "Stärke und Schönheit", "Familie und Freunde"], "„Es gibt zwei Gaben, bei denen viele Menschen Verlust machen: Gesundheit und freie Zeit.“"),
"virtues_043": ("Vervollständige diesen Hadith: „Der Gläubige wird nicht zweimal gestochen…“", ["„…aus demselben Loch“", "„…vom selben Skorpion“", "„…am selben Tag“", "„…von derselben Biene“"], "„La yuldaghu al-mu'minu min juhrin wahidin marratayn“: Der Gläubige lernt aus seinen Fehlern."),
"virtues_044": ("Womit vergleicht der Prophet ﷺ den guten Gefährten, im Gegensatz zum Schmied?", ["Mit dem Moschusverkäufer", "Mit dem Bäcker", "Mit dem Hirten", "Mit dem Stoffhändler"], "„Der gute Gefährte ist wie der Träger von Moschus: Er gibt dir davon, oder du kaufst von ihm, oder du riechst seinen Duft; der schlechte ist wie der Blasebalg des Schmieds.“"),
"virtues_045": ("Wofür ist jeder von uns laut einem Hadith bei al-Buchari „wie ein Hirte“ verantwortlich?", ["Für die, die ihm anvertraut sind", "Für das Wetter", "Für die Sterne", "Für die Ernten anderer"], "„Jeder von euch ist ein Hirte, und jeder ist für seine Herde verantwortlich“: der Herrscher für sein Volk, der Mann für seine Familie, die Frau für ihren Haushalt."),
"virtues_046": ("Was geschieht laut Koran, wenn man das Böse mit dem Besseren abwehrt?", ["Der frühere Feind wird wie ein warmherziger Freund", "Das Böse verschwindet von der Erde", "Man wird reich", "Nichts ändert sich"], "„Wehre das Böse mit dem Besseren ab, und derjenige, zwischen dem und dir Feindschaft war, wird wie ein warmherziger Freund“ (41:34)."),
"virtues_047": ("Wie antworten „die Diener des Allerbarmers“ laut Sure Al-Furqan den Unwissenden, die sie provozieren?", ["Sie sagen: „Frieden!“", "Sie antworten mit Zorn", "Sie verspotten sie", "Sie schlagen sie"], "„Die Diener des Allerbarmers gehen demütig auf der Erde, und wenn die Unwissenden sie ansprechen, sagen sie: Frieden!“ (25:63)."),
"virtues_048": ("Was sagt der Koran über die Verpflichtung (das Versprechen, den Bund)?", ["„Erfüllt die Verpflichtung, denn über die Verpflichtung wird Rechenschaft gefordert“", "„Ein Versprechen bindet niemanden“", "„Versprecht nur den Reichen“", "„Versprecht nie“"], "„Und erfüllt die Verpflichtung, denn über die Verpflichtung wird Rechenschaft gefordert“ (17:34)."),
"virtues_049": ("Von wem sagt der Koran, dass sie „die Brüder der Satane“ sind?", ["Von den Verschwendern", "Von den Reisenden", "Von den Händlern", "Von den Dichtern"], "„Die Verschwender sind die Brüder der Satane, und der Satan ist seinem Herrn gegenüber sehr undankbar“ (17:27)."),
"virtues_050": ("Welches sind die „zwei Worte, leicht auf der Zunge, schwer auf der Waage und dem Allerbarmer lieb“?", ["„Subhana Allahi wa bi-hamdih, subhana Allahi al-Azim“", "„Allahu akbar, al-hamdu li-Llah“", "„La ilaha illa Allah, Muhammad rasulu Allah“", "„Bismi Allah, ma sha'a Allah“"], "„Zwei Worte, leicht auf der Zunge, schwer auf der Waage, dem Allerbarmer lieb: Gepriesen sei Allah und Ihm sei Lob; gepriesen sei Allah, der Gewaltige.“"),
}
